import{z as n,x as o,o as B,c as p,q as A,j as i,D as e,d as t,s,S as l,b as a}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"容量规划案例","description":"","frontmatter":{"title":"容量规划案例","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pe3-capacity-case.md","filePath":"cs/pe3-capacity-case.md","lastUpdated":1791063341000}'),d={name:"cs/pe3-capacity-case.md"};function C(m,E,c,h,F,D){const r=o("Mermaid");return B(),p("div",null,[E[2]||(E[2]=A('<h1 id="容量规划案例" tabindex="-1">容量规划案例 <a class="header-anchor" href="#容量规划案例" aria-label="Permalink to &quot;容量规划案例&quot;">​</a></h1><div class="epigraph"><p>容量不是峰值流量除以单机极限：极限吞吐那个点上的延迟通常已经不可用，按它买机器，等于把 p99 卖了换利用率。</p><footer>—— 据 Beyer 等，Site Reliability Engineering，2016，第 4 章与 Little，Operations Research，1961 口径整理</footer></div><p><a href="/cs/pe3-regression-case">上一课</a>把一次回归从报警追到引入提交，收在「判据先行」上。本课换一个前瞻性的问题：两个月后大促，预估峰值五倍流量，买（或扩）多少机器。容量规划是性能工程里少有的<strong>预先</strong>做的功课——错了没有排查的机会，只有当天晚上。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/pe3-requirements">第一课</a>的需求已经写好：p99 不超过 300 ms，峰值 5 万 QPS，负载模型附了大小分布与突发形状。缺口在于「单机能扛多少 QPS」没有单一答案：它随负载形状、缓存命中率、依赖健康度漂移，是一个函数而不是一个数。不这么做会错在哪：把单机压到 8000 QPS 的极限吞吐，按它乘出机器数——上线后每个实例都站在自己的延迟悬崖边上，峰值的第一个突发就把 p99 推到 3 秒：吞吐达标了，需求里的另一半（延迟分位）碎了。</p><p><span class="marginnote">常见误区：以为容量规划就是一台除法器——「峰值 5 万除以单机 8000，7 台搞定」。除法只回答了「能不能装下」，没回答「装下之后还快不快」。容量规划的核心其实是留多少余量，除出来的裸台数只是余量的起点，不是答案。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>第一步，测容量曲线，不测单点。开环加压（按上一课程的口径：按时间表发请求、不等响应），记录一组（吞吐，延迟）对，画出延迟随吞吐的曲线，找<strong>拐点</strong>——延迟开始非线性上翘的位置。容量取拐点的六到七成做安全水位，而不是极限吞吐。</p><p>第二步，找约束资源并取最小。CPU 不是唯一的账：连接数、内存、线程池、下游配额都可能先到。单机容量等于各资源上限的最小值——压测曲线只暴露最先撞上的那一块，撞墙之后的数据全部失真，要换资源维度重新测。</p><p>第三步，用 Little 定律校验在途量：\\(L=\\lambda W\\)。5 万 QPS 乘 200 ms 平均延迟，全集群任意时刻有一万个请求在途——连接池、队列长度、下游连接数都按这个量级配，而不是按「每实例一百并发」拍脑袋。</p><p>第四步，全链路压测演练预案。单组件压测测不到共享依赖上的排队叠加；用影子流量按峰值形状（突发、读写比照抄第一课的负载模型）打全链路，并验证限流与降级真的在目标水位触发——<a href="/cs/rate-limit-circuit-breaker">限流与熔断</a>的机制没在真实峰值下开过，等于没有。</p>',11)),(B(),i(l,null,{default:e(()=>[s(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E9%9C%80%E6%B1%82%EF%BC%9A5%20%E4%B8%87%20QPS%EF%BC%8Cp99%20%E2%89%A4%20300%20ms%22%5D%20--%3E%20CURVE%5B%22%E5%BC%80%E7%8E%AF%E5%8A%A0%E5%8E%8B%E6%B5%8B%E5%AE%B9%E9%87%8F%E6%9B%B2%E7%BA%BF%22%5D%0A%20%20CURVE%20--%3E%20KNEE%5B%22%E6%89%BE%E6%8B%90%E7%82%B9%EF%BC%8C%E5%8F%96%E5%85%AD%E5%88%B0%E4%B8%83%E6%88%90%E6%B0%B4%E4%BD%8D%22%5D%0A%20%20KNEE%20--%3E%20MINC%5B%22%E7%BA%A6%E6%9D%9F%E8%B5%84%E6%BA%90%E5%8F%96%E6%9C%80%E5%B0%8F%EF%BC%9ACPU%E3%80%81%E8%BF%9E%E6%8E%A5%E3%80%81%E4%B8%8B%E6%B8%B8%E9%85%8D%E9%A2%9D%22%5D%0A%20%20MINC%20--%3E%20LITTLE%5B%22Little%20%E5%AE%9A%E5%BE%8B%E6%A0%A1%E9%AA%8C%E5%9C%A8%E9%80%94%E9%87%8F%22%5D%0A%20%20LITTLE%20--%3E%20E2E%5B%22%E5%85%A8%E9%93%BE%E8%B7%AF%E5%8E%8B%E6%B5%8B%EF%BC%8C%E6%BC%94%E7%BB%83%E9%99%90%E6%B5%81%E4%B8%8E%E9%99%8D%E7%BA%A7%22%5D%0A%20%20E2E%20--%3E%7C%22%E9%A2%84%E6%A1%88%E4%B8%8D%E8%A7%A6%E5%8F%91%22%7C%20ARCH%5B%22%E5%9B%9E%E6%9E%B6%E6%9E%84%EF%BC%9A%E5%85%88%E8%A1%A5%E9%A2%84%E6%A1%88%E5%86%8D%E8%B0%88%E5%AE%B9%E9%87%8F%22%5D%0A%20%20E2E%20--%3E%7C%22%E9%80%9A%E8%BF%87%22%7C%20PLAN%5B%22%E6%89%A9%E5%AE%B9%E8%AE%A1%E5%88%92%EF%BC%9A%E5%8F%B0%E6%95%B0%E4%B8%8E%E5%86%97%E4%BD%99%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[t("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"为什么取拐点不取极限：排队延迟随利用率 \\(\\rho\\) 趋近 1 而发散，\\(W_q\\) 正比于 \\(\\rho/(1-\\rho)\\)——极限吞吐附近延迟是超线性的悬崖，水位六到七成买的不是浪费，是「容量模型错了也不越过悬崖」的保险。为什么容量取最小值：木桶约束，下游配额先到时，本机 CPU 再空也接不住；只按 CPU 算容量是最常见的漏账。为什么预案要演练：过载是罕见状态，罕见状态里的代码路径是测试覆盖最低的路径，第一次真实执行不应发生在真实过载里。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"台数的一笔账：单机拐点 8000 QPS、水位取 70%，单机承载 5600；5 万峰值除以 5600 约等于 9 台，再加 N+2 冗余共 11 台。冗余那两台不是买坏天气——是买容量模型本身的误差，模型越没验证过，冗余越不能省。")],-1)),(B(),i(l,null,{default:e(()=>[s(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20Z1%5B%22%E5%88%A9%E7%94%A8%E7%8E%87%2050%25%EF%BC%9A%E8%88%92%E9%80%82%E5%8C%BA%22%5D%0A%20%20%20%20A%5B%22%E6%8E%92%E9%98%9F%E5%BB%B6%E8%BF%9F%E7%BA%A6%201%20%E5%80%8D%E5%9F%BA%E5%87%86%22%5D%0A%20%20end%0A%20%20subgraph%20Z2%5B%22%E5%88%A9%E7%94%A8%E7%8E%87%2070%25%EF%BC%9A%E5%AE%89%E5%85%A8%E6%B0%B4%E4%BD%8D%22%5D%0A%20%20%20%20B%5B%22%E5%BB%B6%E8%BF%9F%E7%BA%A6%202-3%20%E5%80%8D%EF%BC%8C%E4%BB%8D%E5%9C%A8%20SLO%20%E5%86%85%22%5D%0A%20%20end%0A%20%20subgraph%20Z3%5B%22%E5%88%A9%E7%94%A8%E7%8E%87%2090%25%2B%EF%BC%9A%E6%82%AC%E5%B4%96%22%5D%0A%20%20%20%20C%5B%22%E5%BB%B6%E8%BF%9F%E6%9A%B4%E6%B6%A8%EF%BC%8C%E4%B8%80%E4%B8%AA%E7%AA%81%E5%8F%91%E5%8D%B3%E9%9B%AA%E5%B4%A9%22%5D%0A%20%20end%0A%20%20Z1%20--%3E%7C%22%E6%B5%81%E9%87%8F%E5%A2%9E%E9%95%BF%22%7C%20Z2%0A%20%20Z2%20--%3E%7C%22%E5%86%8D%E6%B6%A8%2020%25%20%E6%B5%81%E9%87%8F%22%7C%20Z3%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=A('<p>这张图回答的问题是：为什么把水位从 70% 再往上推 20% 那么危险？排队延迟 \\(W_q\\) 正比于 \\(\\rho/(1-\\rho)\\)，利用率 50% 时这个系数是 2，70% 时约 3.3，90% 时跳到 10，99% 时是 100——它不是线性爬坡，是加速下坠。70% 水位留出的那 30%，正是「突发来了不越过悬崖」的缓冲带。</p><p><span class="marginnote">数字实例（Little 定律）：高峰期每秒进来 5 万个请求、每个平均待 200 ms，则系统里任意时刻有 \\(50000 \\times 0.2 = 10000\\) 个请求同时在途。直觉类比就像高速路：车流量乘以每辆车通过时间，等于路上常驻的车数——想缩短排队，要么减车流，要么让每辆车更快通过，修「更宽的车位」没用。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>容量按负载模型成立：流量形状变了（读写比反转、请求变大），容量作废重来——第一课的负载模型是合同，本课是它的第一次履约。单点下游不随实例数扩展：一个数据库扛不住时，加应用机器只是把瓶颈推给下游并加重它的排队，扩容计划必须连同下游配额一起做。跨区域的容量与故障演练不在本课——那是容灾课的账。容量与成本是一对：安全水位买的保险有保费，买大的那部分钱如何在 SLO 约束下重新定价，是下一课的题目。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>容量规划交付的是曲线与水位，不是「单机极限 × 台数」的乘法。</li><li>拐点的六到七成是安全水位：买的是延迟稳定性，不是闲置。</li><li>约束资源取最小值；CPU 只是候选之一，下游配额常先到。</li><li>Little 定律 \\(L=\\lambda W\\) 给在途量，连接与队列按它配。</li><li>预案必须在全链路压测里真实触发过，否则等于没有。</li><li>出处：Beyer 等，<em>Site Reliability Engineering</em>，2016，第 4 章；Little, <em>Operations Research</em>, 1961；据本课四步口径整理。</li></ul>',6))])}const f=n(d,[["render",C]]);export{_ as __pageData,f as default};
